4	package api // import "miniflux.app/v2/internal/api"
5	
6	import (
7		json_parser "encoding/json"
8		"errors"
9		"net/http"
10	
11		"miniflux.app/v2/internal/http/request"
12		"miniflux.app/v2/internal/http/response"
13		"miniflux.app/v2/internal/model"
14		"miniflux.app/v2/internal/validator"
15	)
16	
17	// @effects: reads users
18	func (h *handler) currentUserHandler(w http.ResponseWriter, r *http.Request) {
19		user, err := h.store.UserByID(request.UserID(r))
20		if err != nil {
21			response.JSONServerError(w, r, err)
22			return
23		}
24	
25		if user == nil {
26			response.JSONNotFound(w, r)
27			return
28		}
29	
30		response.JSON(w, r, user)
31	}
32	
33	// @effects: reads users, writes categories, writes integrations, writes users
34	func (h *handler) createUserHandler(w http.ResponseWriter, r *http.Request) {
35		if !request.IsAdminUser(r) {
36			response.JSONForbidden(w, r)
37			return
38		}
39	
40		var userCreationRequest model.UserCreationRequest
41		if err := json_parser.NewDecoder(r.Body).Decode(&userCreationRequest); err != nil {
42			response.JSONBadRequest(w, r, err)
43			return
44		}
45	
46		if validationErr := validator.ValidateUserCreationWithPassword(h.store, &userCreationRequest); validationErr != nil {
47			response.JSONBadRequest(w, r, validationErr.Error())
48			return
49		}
50	
51		user, err := h.store.CreateUser(&userCreationRequest)
52		if err != nil {
53			response.JSONServerError(w, r, err)
54			return
55		}
56	
57		response.JSONCreated(w, r, user)
58	}
59	
60	// @effects: reads users, writes users, writes web_sessions, mut
61	func (h *handler) updateUserHandler(w http.ResponseWriter, r *http.Request) {
62		userID := request.RouteInt64Param(r, "userID")
63		if userID == 0 {
64			response.JSONBadRequest(w, r, errors.New("invalid user ID"))
65			return
66		}
67	
68		var userModificationRequest model.UserModificationRequest
69		if err := json_parser.NewDecoder(r.Body).Decode(&userModificationRequest); err != nil {
70			response.JSONBadRequest(w, r, err)
71			return
72		}
73	
74		originalUser, err := h.store.UserByID(userID)
75		if err != nil {
76			response.JSONServerError(w, r, err)
77			return
78		}
79	
80		if originalUser == nil {
81			response.JSONNotFound(w, r)
82			return
83		}
84	
85		if !request.IsAdminUser(r) {
86			if originalUser.ID != request.UserID(r) {
87				response.JSONForbidden(w, r)
88				return
89			}
90	
91			if userModificationRequest.IsAdmin != nil && *userModificationRequest.IsAdmin {
92				response.JSONBadRequest(w, r, errors.New("only administrators can change permissions of standard users"))
93				return
94			}
95		}
96	
97		if validationErr := validator.ValidateUserModification(h.store, originalUser.ID, &userModificationRequest); validationErr != nil {
98			response.JSONBadRequest(w, r, validationErr.Error())
99			return
100		}
101	
102		userModificationRequest.Patch(originalUser)
103		if err = h.store.UpdateUser(originalUser); err != nil {
104			response.JSONServerError(w, r, err)
105			return
106		}
107	
108		if userModificationRequest.Password != nil {
109			if err := h.store.RemoveUserWebSessionsExcept(originalUser.ID, ""); err != nil {
110				response.JSONServerError(w, r, err)
111				return
112			}
113		}
114	
115		response.JSONCreated(w, r, originalUser)
116	}
117	
118	// @effects: reads users, writes entries
119	func (h *handler) markUserAsReadHandler(w http.ResponseWriter, r *http.Request) {
120		userID := request.RouteInt64Param(r, "userID")
121		if userID == 0 {
122			response.JSONBadRequest(w, r, errors.New("invalid user ID"))
123			return
124		}
125	
126		if userID != request.UserID(r) {
127			response.JSONForbidden(w, r)
128			return
129		}
130	
131		user, err := h.store.UserByID(userID)
132		if err != nil {
133			response.JSONServerError(w, r, err)
134			return
135		}
136	
137		if user == nil {
138			response.JSONNotFound(w, r)
139			return
140		}
141	
142		if err := h.store.MarkAllAsRead(userID); err != nil {
143			response.JSONServerError(w, r, err)
144			return
145		}
146	
147		response.NoContent(w, r)
148	}
149	
150	// @effects: reads integrations, reads users
151	func (h *handler) getIntegrationsStatusHandler(w http.ResponseWriter, r *http.Request) {
152		userID := request.UserID(r)
153		user, err := h.store.UserByID(userID)
154		if err != nil {
155			response.JSONServerError(w, r, err)
156			return
157		}
158	
159		if user == nil {
160			response.JSONNotFound(w, r)
161			return
162		}
163	
164		hasIntegrations := h.store.HasSaveEntry(userID)
165	
166		response.JSON(w, r, integrationsStatusResponse{HasIntegrations: hasIntegrations})
167	}
168	
169	// @effects: reads users
170	func (h *handler) usersHandler(w http.ResponseWriter, r *http.Request) {
171		if !request.IsAdminUser(r) {
172			response.JSONForbidden(w, r)
173			return
174		}
175	
176		users, err := h.store.Users()
177		if err != nil {
178			response.JSONServerError(w, r, err)
179			return
180		}
181	
182		users.UseTimezone(request.UserTimezone(r))
183		response.JSON(w, r, users)
184	}
185	
186	// @effects: reads users
187	func (h *handler) dispatchUserLookupHandler(w http.ResponseWriter, r *http.Request) {
188		identifier := request.RouteStringParam(r, "identifier")
189		userID := request.RouteInt64Param(r, "identifier")
190		if userID > 0 {
191			r.SetPathValue("userID", identifier)
192			h.userByIDHandler(w, r)
193			return
194		}
195	
196		r.SetPathValue("username", identifier)
197		h.userByUsernameHandler(w, r)
198	}
199	
200	// @effects: reads users
201	func (h *handler) userByIDHandler(w http.ResponseWriter, r *http.Request) {
202		if !request.IsAdminUser(r) {
203			response.JSONForbidden(w, r)
204			return
205		}
206	
207		userID := request.RouteInt64Param(r, "userID")
208		if userID == 0 {
209			response.JSONBadRequest(w, r, errors.New("invalid user ID"))
210			return
211		}
212	
213		user, err := h.store.UserByID(userID)
214		if err != nil {
215			response.JSONServerError(w, r, err)
216			return
217		}
218	
219		if user == nil {
220			response.JSONNotFound(w, r)
221			return
222		}
223	
224		user.UseTimezone(request.UserTimezone(r))
225		response.JSON(w, r, user)
226	}
227	
228	// @effects: reads users
229	func (h *handler) userByUsernameHandler(w http.ResponseWriter, r *http.Request) {
230		if !request.IsAdminUser(r) {
231			response.JSONForbidden(w, r)
232			return
233		}
234	
235		username := request.RouteStringParam(r, "username")
236		user, err := h.store.UserByUsername(username)
237		if err != nil {
238			response.JSONServerError(w, r, err)
239			return
240		}
241	
242		if user == nil {
243			response.JSONNotFound(w, r)
244			return
245		}
246	
247		response.JSON(w, r, user)
248	}
249	
250	// @effects: reads users, writes users
251	func (h *handler) removeUserHandler(w http.ResponseWriter, r *http.Request) {
252		if !request.IsAdminUser(r) {
253			response.JSONForbidden(w, r)
254			return
255		}
256	
257		userID := request.RouteInt64Param(r, "userID")
258		if userID == 0 {
259			response.JSONBadRequest(w, r, errors.New("invalid user ID"))
260			return
261		}
262	
263		user, err := h.store.UserByID(userID)
264		if err != nil {
265			response.JSONServerError(w, r, err)
266			return
267		}
268	
269		if user == nil {
270			response.JSONNotFound(w, r)
271			return
272		}
273	
274		if user.ID == request.UserID(r) {
275			response.JSONBadRequest(w, r, errors.New("you cannot remove yourself"))
276			return
277		}
278	
279		if err := h.store.RemoveUser(user.ID); err != nil {
280			response.JSONServerError(w, r, err)
281			return
282		}
283	
284		response.NoContent(w, r)
285	}
