1	// SPDX-FileCopyrightText: Copyright The Miniflux Authors. All rights reserved.
2	// SPDX-License-Identifier: Apache-2.0
3	
4	package api // import "miniflux.app/v2/internal/api"
5	
6	import (
7		json_parser "encoding/json"
8		"errors"
9		"log/slog"
10		"net/http"
11		"time"
12	
13		"miniflux.app/v2/internal/config"
14		"miniflux.app/v2/internal/http/request"
15		"miniflux.app/v2/internal/http/response"
16		"miniflux.app/v2/internal/locale"
17		"miniflux.app/v2/internal/model"
18		feedHandler "miniflux.app/v2/internal/reader/handler"
19		"miniflux.app/v2/internal/storage"
20		"miniflux.app/v2/internal/validator"
21	)
22	
23	// @effects: reads categories, reads entries, reads entry_tombstones, reads feeds, reads icons, reads users, writes enclosures, writes entries, writes feed_icons, writes feeds, writes icons, net, mut
24	func (h *handler) createFeedHandler(w http.ResponseWriter, r *http.Request) {
25		userID := request.UserID(r)
26	
27		var feedCreationRequest model.FeedCreationRequest
28		if err := json_parser.NewDecoder(r.Body).Decode(&feedCreationRequest); err != nil {
29			response.JSONBadRequest(w, r, err)
30			return
31		}
32	
33		// Make the feed category optional for clients who don't support categories.
34		if feedCreationRequest.CategoryID == 0 {
35			category, err := h.store.FirstCategory(userID)
36			if err != nil {
37				if errors.Is(err, storage.ErrNoCategory) {
38					response.JSONBadRequest(w, r, locale.NewLocalizedError("error.feed_category_not_found").Error())
39					return
40				}
41				response.JSONServerError(w, r, err)
42				return
43			}
44			if category == nil {
45				response.JSONBadRequest(w, r, locale.NewLocalizedError("error.feed_category_not_found").Error())
46				return
47			}
48			feedCreationRequest.CategoryID = category.ID
49		}
50	
51		if validationErr := validator.ValidateFeedCreation(h.store, userID, &feedCreationRequest); validationErr != nil {
52			response.JSONBadRequest(w, r, validationErr.Error())
53			return
54		}
55	
56		feed, localizedError := feedHandler.CreateFeed(h.store, userID, &feedCreationRequest)
57		if localizedError != nil {
58			response.JSONServerError(w, r, localizedError.Error())
59			return
60		}
61	
62		response.JSONCreated(w, r, &feedCreationResponse{FeedID: feed.ID})
63	}
64	
65	// @effects: reads categories, reads entries, reads entry_tombstones, reads feed_icons, reads feeds, reads icons, reads integrations, reads users, writes enclosures, writes entries, writes feed_icons, writes feeds, writes icons, net, mut
66	func (h *handler) refreshFeedHandler(w http.ResponseWriter, r *http.Request) {
67		feedID := request.RouteInt64Param(r, "feedID")
68		if feedID == 0 {
69			response.JSONBadRequest(w, r, errors.New("invalid feed ID"))
70			return
71		}
72	
73		userID := request.UserID(r)
74		exists, err := h.store.FeedExists(userID, feedID)
75		if err != nil {
76			response.JSONServerError(w, r, err)
77			return
78		}
79		if !exists {
80			response.JSONNotFound(w, r)
81			return
82		}
83	
84		// force=true mirrors the web UI's forced refresh: it bypasses the HTTP cache
85		// and reprocesses (and re-scrapes) entries that are already stored.
86		forceRefresh := request.QueryBoolParam(r, "force", false)
87		localizedError := feedHandler.RefreshFeed(h.store, userID, feedID, forceRefresh)
88		if localizedError != nil {
89			response.JSONServerError(w, r, localizedError.Error())
90			return
91		}
92	
93		response.NoContent(w, r)
94	}
95	
96	// @effects: reads feeds
97	func (h *handler) refreshAllFeedsHandler(w http.ResponseWriter, r *http.Request) {
98		userID := request.UserID(r)
99	
100		jobs, err := h.store.NewBatchBuilder().
101			WithErrorLimit(config.Opts.PollingParsingErrorLimit()).
102			WithoutDisabledFeeds().
103			WithNextCheckExpired().
104			WithUserID(userID).
105			WithLimitPerHost(config.Opts.PollingLimitPerHost()).
106			FetchJobs()
107		if err != nil {
108			response.JSONServerError(w, r, err)
109			return
110		}
111	
112		slog.Info(
113			"Triggered a manual refresh of all feeds from the API",
114			slog.Int64("user_id", userID),
115			slog.Int("nb_jobs", len(jobs)),
116		)
117	
