426	func subscribe(newFeed Stream, category Stream, title string, store *storage.Storage, userID int64) (*model.Feed, error) {
427		destCategory, err := getOrCreateCategory(category, store, userID)
428		if err != nil {
429			if errors.Is(err, storage.ErrNoCategory) {
430				return nil, errCategoryNotFound
431			}
432			return nil, err
433		}
434		if destCategory == nil {
435			return nil, errCategoryNotFound
436		}
437	
438		feedRequest := model.FeedCreationRequest{
439			FeedURL:    newFeed.ID,
440			CategoryID: destCategory.ID,
441		}
442		verr := validator.ValidateFeedCreation(store, userID, &feedRequest)
443		if verr != nil {
444			return nil, verr.Error()
445		}
446	
447		created, localizedError := mff.CreateFeed(store, userID, &feedRequest)
448		if localizedError != nil {
449			return nil, localizedError.Error()
450		}
451	
452		if title != "" {
453			feedModification := model.FeedModificationRequest{
454				Title: &title,
455			}
456			feedModification.Patch(created)
457			if err := store.UpdateFeed(created); err != nil {
458				return nil, err
459			}
460		}
461	
462		return created, nil
463	}
